// This file is generated by AI.

// `game/config.txt` 的解析与改写 (纯函数)。
//
// 为什么前端也要有一份解析: 侧栏与开始界面要显示"名称/识别码/封面", 而这些内容可能
// 正开在编辑器里且**还没存盘** —— 那时磁盘上那份是旧的, 只有文档里的这份是最新的。
// 规则与语言服务 (crates/webgal-language-core/src/resource/config.rs) 保持一致:
// 首个 `:` 分隔键值, 行内首个 `;` 之后是注释, 空行与纯注释行不是配置项。

/** 一条配置 (`ConfigItem` 的对应物)。 */
export interface GameConfigEntry {
  name: string;
  value: string;
  /** 行内注释 (`;` 之后到行尾) */
  comment: string;
}

/** 侧栏 / 开始界面需要的几个参数。 */
export interface GameConfigSummary {
  /** `Game_name` */
  name: string;
  /** `Game_key` */
  gameKey: string;
  /** `Description` */
  description: string;
  /** `Title_img` (仅文件名) */
  titleImg: string;
  /** `Title_bgm` (仅文件名) */
  titleBgm: string;
  /** `Game_Logo` (可能是 `|` 分隔的多个文件) */
  logo: string;
}

const EMPTY_SUMMARY: GameConfigSummary = {
  name: '',
  gameKey: '',
  description: '',
  titleImg: '',
  titleBgm: '',
  logo: '',
};

/** 解析 config.txt 全文。 */
export function parseGameConfigText(text: string): GameConfigEntry[] {
  const entries: GameConfigEntry[] = [];
  for (const line of text.split(/\r?\n/)) {
    const entry = parseLine(line);
    if (entry) entries.push(entry);
  }
  return entries;
}

/** 解析单行; 不是配置项时返回 null。 */
function parseLine(line: string): GameConfigEntry | null {
  const trimmed = line.trim();
  if (trimmed === '' || trimmed.startsWith(';')) return null;

  const semicolon = trimmed.indexOf(';');
  const content = semicolon === -1 ? trimmed : trimmed.slice(0, semicolon);
  const comment = semicolon === -1 ? '' : trimmed.slice(semicolon + 1).trim();

  const colon = content.indexOf(':');
  if (colon === -1) return null;
  const name = content.slice(0, colon).trim();
  const value = content.slice(colon + 1).trimEnd();
  if (!name || !value) return null;

  return { name, value, comment };
}

/** 取值: 同名配置取**最后**一次出现 (与 `Config::get_config` 一致)。 */
export function gameConfigValue(entries: GameConfigEntry[], name: string): string {
  for (let index = entries.length - 1; index >= 0; index -= 1) {
    if (entries[index].name === name) return entries[index].value;
  }
  return '';
}

/** 汇总侧栏要用的几个参数。 */
export function gameConfigSummary(entries: GameConfigEntry[]): GameConfigSummary {
  if (entries.length === 0) return { ...EMPTY_SUMMARY };
  return {
    name: gameConfigValue(entries, 'Game_name'),
    gameKey: gameConfigValue(entries, 'Game_key'),
    description: gameConfigValue(entries, 'Description'),
    titleImg: gameConfigValue(entries, 'Title_img'),
    titleBgm: gameConfigValue(entries, 'Title_bgm'),
    logo: gameConfigValue(entries, 'Game_Logo'),
  };
}

/**
 * 改写一条配置 (保留行内注释), 不存在时追加到文件末尾。
 *
 * 与语言服务的 `Display` 一致输出 `name:value;`, 因此改一行不会顺带重排整个文件。
 * `text` 为空时直接生成一行, 用于给没有 config.txt 的项目补上第一个参数。
 */
export function setGameConfigValue(text: string, name: string, value: string): string {
  return setGameConfigValues(text, { [name]: value });
}

/** 一次改写多条配置 (按给定顺序应用)。 */
export function setGameConfigValues(text: string, values: Record<string, string>): string {
  const empty = text.trim() === '';
  let lines = empty ? [] : text.split(/\r?\n/);
  // 末尾换行会分出一个空字符串, 先摘掉, 最后再按原样接回去
  const trailingNewline = !empty && lines[lines.length - 1] === '';
  if (trailingNewline) lines = lines.slice(0, -1);

  for (const [name, value] of Object.entries(values)) {
    let target = -1;
    for (let index = lines.length - 1; index >= 0; index -= 1) {
      if (parseLine(lines[index])?.name === name) {
        target = index;
        break;
      }
    }
    const comment = target === -1 ? '' : (parseLine(lines[target])?.comment ?? '');
    const line = comment ? `${name}:${value}; ${comment}` : `${name}:${value};`;
    if (target === -1) lines.push(line);
    else lines[target] = line;
  }

  const result = lines.join('\n');
  return trailingNewline ? `${result}\n` : result;
}
